 if(a==='toggleSources'){S.showSources=!S.showSources;render();return;}
 if(a==='unsave'){unsave(q('#save-pop')?.dataset.key);return;}
 if(a==='deleteCollection'){const id=el.dataset.col,undo=libSnapshot();collections=collections.filter(c=>c.id!==id);persist(api.collections.remove(id),undo,'your library');S.libCol='all';render();toast('Collection deleted · its papers stay in your library');return;}
