 if(a==='detail-save'&&selectedPaper){const p=selectedPaper,key=paperId(p),existing=paperReading(p),undo=libSnapshot();bookmarks=existing?bookmarks.filter(x=>paperKey(x)!==key):[...bookmarks,p];persistLib(existing?api.library.remove(key):api.library.save(p),undo);toast(existing?'Removed from reading list':'Added to your reading list');render();return;}
 if(a==='detail-share'&&selectedPaper){const url=link(selectedPaper);if(url){navigator.clipboard?.writeText(url).then(()=>toast('Citation link copied')).catch(()=>toast('Copy this page using your browser'));}else toast('Demo paper has no real publication link');return;}
 if(a==='save-note'&&selectedPaper){const k=paperId(selectedPaper),prev=paperNotes[k],text=q('#paper-notes-input')?.value||'';paperNotes[k]=text;persist(api.notes.save(k,text),()=>{paperNotes[k]=prev},'your notes');toast('Private notes saved');return;}
 if(a==='start-paper-thread'&&selectedPaper){newDiscussion({paper:selectedPaper,fromPaper:true});return;}
