 if(d.topic!==undefined){if(d.topicGo!==undefined){if(S.view!=='feed')navigate('feed');S.scope='discover';f.topic=d.topic;render();if(dataMode==='live')fetchPapers();scrollTo({top:0,behavior:'instant'});return}f.topic=f.topic===d.topic?'':d.topic;refreshFeed(false);return}
