/* ---------- API sync ---------- */
// Optimistic writes: local state changes first and the view re-renders; if the API rejects, `undo` restores it and the user is told.
function persist(task,undo,what='that change'){return Promise.resolve(task).catch(err=>{console.error(err);undo?.();render();toast(`Couldn’t save ${what}. ${describeError(err)}`)})}
// Creating records waits for the API (it assigns ids and authors): the form is disabled meanwhile and stays open on failure.
async function busy(form,what,task){const ctl=[...form.querySelectorAll('button,input,select,textarea')].filter(x=>!x.disabled);ctl.forEach(x=>x.disabled=true);form.setAttribute('aria-busy','true');try{await task()}catch(err){console.error(err);toast(`Couldn’t save ${what}. ${describeError(err)}`)}finally{ctl.forEach(x=>x.disabled=false);form.removeAttribute('aria-busy')}}
// Preferences: every change is sent as a partial update; a failure restores the last state the API confirmed.
let savedPrefs=null;
function applyPrefs(p){p=structuredClone(p);followed=p.following;pinned=p.pinned;feedJournals=p.feedJournals;specJournals=p.specJournals;journalTopics=p.journalTopics;specJournalTopics=p.specJournalTopics;dataMode=p.dataMode;S.scope=p.scope}
function savePrefs(patch){return persist(api.preferences.update(patch).then(p=>{savedPrefs=p}),()=>{if(savedPrefs)applyPrefs(savedPrefs)},'your preferences')}

/* ---------- Startup: load the session and community content, then route ---------- */
function applySession(st){profile=st.user;roleTags=st.roleTags;savedPrefs=st.preferences;applyPrefs(st.preferences);bookmarks=st.bookmarks.map(b=>b.paper);bookmarks.forEach(reg);collections=st.collections;appraisals=st.appraisals;paperRatings=st.ratings;paperNotes=st.notes;interestReasons=st.interests;interests=Object.keys(st.interests);paperComments=st.myPaperComments}
export async function boot(){const content=q('#content');content.setAttribute('aria-busy','true');content.innerHTML='<div class="loading"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><p class="feed-status-msg"><span class="small-spinner"></span> Loading Rounds…</p>';
 try{const [session,community,threadList,projects,jobs]=await Promise.all([api.session.load(),api.content.load(),api.discussions.list(),api.projects.list(),api.jobs.list()]);
  applySession(session);catalog=community.papers;catalog.forEach(reg);highlights=community.highlights;topicTrends=community.topicTrends;threads=threadList;communityProjects=projects.filter(p=>!p.sample);ideaProjects=projects.filter(p=>p.sample);communityJobs=jobs.filter(j=>!j.sample);ideaJobs=jobs.filter(j=>j.sample)}
 catch(err){console.error(err);content.removeAttribute('aria-busy');content.innerHTML=empty('Couldn’t load Rounds',describeError(err)+' Check your connection and try again.','Try again','data-action="boot-retry"');return}
 content.removeAttribute('aria-busy');
 const start=location.hash.slice(1);if(specs.some(s=>s.id===start))navigate('specialty',start);else navigate(['feed','explore','discussions','collaborate','opportunities','library','profile','about','saved','activity','following','home'].includes(start)?start:'feed')}
